use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut keys: Vec<int> = [0]
    let mut lefts: Vec<int> = [0]
    let mut rights: Vec<int> = [0]
    let mut root: int = 0
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        let mut arg: int = 0
        if parts.len() > 1 {
            arg = parts[1].parse::<int>().unwrap_or(0)
        }
        if cmd == "insert" {
            let mut cur: int = root
            let mut parent: int = 0
            let mut goleft = false
            let mut found = false
            while cur != 0 {
                if keys[cur] == arg {
                    found = true
                    break
                }
                parent = cur
                if arg < keys[cur] {
                    goleft = true
                    cur = lefts[cur]
                } else {
                    goleft = false
                    cur = rights[cur]
                }
            }
            if found {
                println("dup")
            } else {
                let idx: int = keys.len() as int
                keys.push(arg)
                lefts.push(0)
                rights.push(0)
                if parent == 0 {
                    root = idx
                } else if goleft {
                    lefts[parent] = idx
                } else {
                    rights[parent] = idx
                }
                println("ok")
            }
        } else if cmd == "contains" {
            let mut cur: int = root
            let mut found = false
            while cur != 0 {
                if keys[cur] == arg {
                    found = true
                    break
                }
                if arg < keys[cur] {
                    cur = lefts[cur]
                } else {
                    cur = rights[cur]
                }
            }
            if found {
                println("yes")
            } else {
                println("no")
            }
        } else if cmd == "delete" {
            let mut cur: int = root
            let mut parent: int = 0
            let mut goleft = false
            let mut found = false
            while cur != 0 {
                if keys[cur] == arg {
                    found = true
                    break
                }
                parent = cur
                if arg < keys[cur] {
                    goleft = true
                    cur = lefts[cur]
                } else {
                    goleft = false
                    cur = rights[cur]
                }
            }
            if !found {
                println("missing")
            } else {
                if lefts[cur] != 0 && rights[cur] != 0 {
                    let mut sp: int = cur
                    let mut s: int = rights[cur]
                    while lefts[s] != 0 {
                        sp = s
                        s = lefts[s]
                    }
                    keys[cur] = keys[s]
                    let sr: int = rights[s]
                    if sp == cur {
                        rights[sp] = sr
                    } else {
                        lefts[sp] = sr
                    }
                } else {
                    let mut child: int = lefts[cur]
                    if child == 0 {
                        child = rights[cur]
                    }
                    if parent == 0 {
                        root = child
                    } else if goleft {
                        lefts[parent] = child
                    } else {
                        rights[parent] = child
                    }
                }
                println("ok")
            }
        } else if cmd == "inorder" {
            if root == 0 {
                println("<empty>")
            } else {
                let mut out: Vec<string> = []
                let mut stack: Vec<int> = []
                let mut cur: int = root
                while cur != 0 || stack.len() > 0 {
                    while cur != 0 {
                        stack.push(cur)
                        cur = lefts[cur]
                    }
                    let n: int = stack.pop().unwrap_or(0)
                    out.push("${keys[n]}")
                    cur = rights[n]
                }
                println(out.join(" "))
            }
        } else if cmd == "height" {
            let mut best: int = 0
            if root != 0 {
                let mut nodes: Vec<int> = [root]
                let mut depths: Vec<int> = [1]
                while nodes.len() > 0 {
                    let n: int = nodes.pop().unwrap_or(0)
                    let d: int = depths.pop().unwrap_or(0)
                    if d > best {
                        best = d
                    }
                    if lefts[n] != 0 {
                        nodes.push(lefts[n])
                        depths.push(d + 1)
                    }
                    if rights[n] != 0 {
                        nodes.push(rights[n])
                        depths.push(d + 1)
                    }
                }
            }
            println("${best}")
        } else if cmd == "min" {
            if root == 0 {
                println("empty")
            } else {
                let mut cur: int = root
                while lefts[cur] != 0 {
                    cur = lefts[cur]
                }
                println("${keys[cur]}")
            }
        } else if cmd == "max" {
            if root == 0 {
                println("empty")
            } else {
                let mut cur: int = root
                while rights[cur] != 0 {
                    cur = rights[cur]
                }
                println("${keys[cur]}")
            }
        }
    }
}

